// Construction executes the actual Hero, equipment, fashion and mesh recipe code.
// Managed hierarchy implements TRS/reparenting and deferred destruction; shaders/cloth
// simulation and color lookup are doubles. Relic clearance uses actual transformed vertices;
// weapon class/grip attachment uses real hierarchy/anchors, not a general triangle-intersection solver.
// This is static authored geometry, not animated collision/render proof.
using System;using System.Collections;using System.Collections.Generic;using System.Linq;using System.Reflection;using UnityEngine;using Emberfall;
namespace UnityEngine {
 public class Object {
  public static readonly List<Object> All=new List<Object>();public string name;public bool destroyed;static readonly HashSet<Object> pending=new HashSet<Object>();public Object(){All.Add(this);}
  public static void Destroy(Object o){if(o!=null&&!o.destroyed)pending.Add(o);}public static void Flush(){while(pending.Count>0){var o=pending.First();pending.Remove(o);if(o.destroyed)continue;if(o is GameObject g){foreach(var child in g.transform.children.ToArray())Destroy(child.gameObject);foreach(var c in g.components.ToArray()){GameObject.Call(c,"OnDestroy");c.destroyed=true;}g.transform.parent?.children.Remove(g.transform);}o.destroyed=true;}}
 }
 public class Component:Object {public GameObject gameObject;public Transform transform=>gameObject.transform;public T GetComponent<T>()where T:Component=>gameObject.GetComponent<T>();public T[] GetComponentsInChildren<T>(bool inactive)where T:Component=>gameObject.GetComponentsInChildren<T>(inactive);}
 public class MonoBehaviour:Component {}
 public class GameObject:Object {
  public bool activeSelf=true;public bool activeInHierarchy=>activeSelf&&!destroyed&&(transform.parent==null||transform.parent.gameObject.activeInHierarchy);public Transform transform;public readonly List<Component> components=new List<Component>();
  public GameObject(string n){name=n;transform=new Transform{gameObject=this};components.Add(transform);}public void SetActive(bool a){activeSelf=a;}
  public T AddComponent<T>()where T:Component,new(){var c=new T{gameObject=this};components.Add(c);Call(c,"Awake");return c;}public T GetComponent<T>()where T:Component=>components.OfType<T>().FirstOrDefault(c=>!c.destroyed);
  public T[] GetComponentsInChildren<T>(bool inactive)where T:Component{var list=new List<T>();if(!destroyed&&(inactive||activeInHierarchy))list.AddRange(components.OfType<T>().Where(c=>!c.destroyed));foreach(var child in transform.children.ToArray())list.AddRange(child.gameObject.GetComponentsInChildren<T>(inactive));return list.ToArray();}
  public static void Call(object o,string m)=>o.GetType().GetMethod(m,BindingFlags.Instance|BindingFlags.NonPublic)?.Invoke(o,null);
 }
 public class Transform:Component,IEnumerable<Transform> {
  public new string name=>gameObject.name;public Transform parent;public List<Transform> children=new List<Transform>();public Vector3 localPosition,localScale=Vector3.one;public Quaternion localRotation=Quaternion.identity;
  public Vector3 position{get=>TransformPoint(Vector3.zero);set=>localPosition=parent==null?value:parent.InverseTransformPoint(value);}public Quaternion rotation=>parent==null?localRotation:parent.rotation*localRotation;
  public Vector3 TransformPoint(Vector3 p){var q=localPosition+localRotation*Vector3.Scale(p,localScale);return parent==null?q:parent.TransformPoint(q);}public Vector3 InverseTransformPoint(Vector3 p){if(parent!=null)p=parent.InverseTransformPoint(p);p=Quaternion.Inverse(localRotation)*(p-localPosition);return new Vector3(p.x/localScale.x,p.y/localScale.y,p.z/localScale.z);}
  public void SetParent(Transform p,bool world){Vector3 at=position;Quaternion rot=rotation;parent?.children.Remove(this);parent=p;p?.children.Add(this);if(world){position=at;localRotation=p==null?rot:Quaternion.Inverse(p.rotation)*rot;}}
  public Transform Find(string n)=>children.FirstOrDefault(c=>c.name==n&&!c.gameObject.destroyed);public IEnumerator<Transform> GetEnumerator()=>children.GetEnumerator();IEnumerator IEnumerable.GetEnumerator()=>GetEnumerator();
 }
 public struct Vector3 {
  public float x,y,z;public Vector3(float a,float b,float c){x=a;y=b;z=c;}public static Vector3 zero=>new Vector3();public static Vector3 one=>new Vector3(1,1,1);public static Vector3 up=>new Vector3(0,1,0);public static Vector3 down=>new Vector3(0,-1,0);public static Vector3 right=>new Vector3(1,0,0);public static Vector3 left=>new Vector3(-1,0,0);public static Vector3 forward=>new Vector3(0,0,1);public static Vector3 back=>new Vector3(0,0,-1);public float sqrMagnitude=>x*x+y*y+z*z;public float magnitude=>(float)Math.Sqrt(x*x+y*y+z*z);public Vector3 normalized=>magnitude>0?this/magnitude:zero;
  public static Vector3 operator+(Vector3 a,Vector3 b)=>new Vector3(a.x+b.x,a.y+b.y,a.z+b.z);public static Vector3 operator-(Vector3 a,Vector3 b)=>new Vector3(a.x-b.x,a.y-b.y,a.z-b.z);public static Vector3 operator-(Vector3 a)=>a*-1;public static Vector3 operator*(Vector3 a,float b)=>new Vector3(a.x*b,a.y*b,a.z*b);public static Vector3 operator*(float b,Vector3 a)=>a*b;public static Vector3 operator/(Vector3 a,float b)=>a*(1/b);public static Vector3 Scale(Vector3 a,Vector3 b)=>new Vector3(a.x*b.x,a.y*b.y,a.z*b.z);public static Vector3 Cross(Vector3 a,Vector3 b)=>new Vector3(a.y*b.z-a.z*b.y,a.z*b.x-a.x*b.z,a.x*b.y-a.y*b.x);public override string ToString()=>$"({x:F3},{y:F3},{z:F3})";
 }
 public struct Vector2{public float x,y;public Vector2(float a,float b){x=a;y=b;}}
 public struct Quaternion {internal System.Numerics.Quaternion q;public static Quaternion identity=>new Quaternion{q=System.Numerics.Quaternion.Identity};public static Quaternion Euler(float x,float y,float z)=>new Quaternion{q=System.Numerics.Quaternion.CreateFromYawPitchRoll(y*Mathf.PI/180,x*Mathf.PI/180,z*Mathf.PI/180)};public static Quaternion Inverse(Quaternion a)=>new Quaternion{q=System.Numerics.Quaternion.Inverse(a.q)};public static Quaternion operator*(Quaternion a,Quaternion b)=>new Quaternion{q=a.q*b.q};public static Vector3 operator*(Quaternion a,Vector3 p){var v=System.Numerics.Vector3.Transform(new System.Numerics.Vector3(p.x,p.y,p.z),a.q);return new Vector3(v.X,v.Y,v.Z);}}
 public struct Color{public float r,g,b,a;public Color(float r,float g,float b,float a=1){this.r=r;this.g=g;this.b=b;this.a=a;}public static Color black=>new Color(0,0,0);public static Color white=>new Color(1,1,1);public static Color operator*(Color c,float f)=>new Color(c.r*f,c.g*f,c.b*f,c.a*f);public static Color Lerp(Color a,Color b,float t)=>new Color(a.r+(b.r-a.r)*t,a.g+(b.g-a.g)*t,a.b+(b.b-a.b)*t,a.a+(b.a-a.a)*t);}
 public class Shader {public static Shader Find(string n)=>new Shader();}
 public class Material:Object {public Color color;public bool enableInstancing;public Material(Shader s){}public bool HasProperty(string n)=>true;public void SetFloat(string n,float v){}public void EnableKeyword(string s){}public void SetColor(string n,Color c){}}
 public class Mesh:Object {public Vector3[] vertices,normals;public Vector2[] uv;public int[] triangles;public void RecalculateNormals(){}public void RecalculateBounds(){}}
