 public enum PrimitiveType{Cube,Sphere,Capsule,Cylinder,Quad}public enum RuntimeInitializeLoadType{SubsystemRegistration}public class RuntimeInitializeOnLoadMethodAttribute:Attribute{public RuntimeInitializeOnLoadMethodAttribute(RuntimeInitializeLoadType t){}}
 public static class Random{public static float value=>.5f;}public static class Time{public static float deltaTime=.016f;}
 public static class Mathf{public static float Clamp01(float x)=>Math.Max(0,Math.Min(1,x));public const float PI=(float)Math.PI,Deg2Rad=PI/180;public static float Sin(float x)=>(float)Math.Sin(x);public static float Cos(float x)=>(float)Math.Cos(x);public static float Abs(float x)=>Math.Abs(x);public static int Min(int x,int y)=>Math.Min(x,y);public static int Clamp(int x,int a,int b)=>Math.Max(a,Math.Min(b,x));public static float Clamp(float x,float a,float b)=>Math.Max(a,Math.Min(b,x));public static float Repeat(float x,float y)=>x-(float)Math.Floor(x/y)*y;}
