public static class EquipmentCompositionProductionTests {
 static int checks;static void Check(bool ok,string text){checks++;if(!ok)throw new Exception(text);}static int Live<T>()where T:UnityEngine.Object=>UnityEngine.Object.All.OfType<T>().Count(x=>!x.destroyed);
 static Transform Find(CombatModel m,string name)=>m.GetComponentsInChildren<Transform>(true).Single(x=>x.name==name&&!x.gameObject.destroyed);
 static Vector3[] Vertices(Transform t,Transform space)=>t.GetComponentsInChildren<MeshFilter>(false).SelectMany(f=>f.sharedMesh.vertices.Select(v=>space.InverseTransformPoint(f.transform.TransformPoint(v)))).ToArray();
 static void ResetMeshes(){typeof(CostumeMeshLibrary).GetMethod("Reset",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,null);typeof(ProceduralVisuals).GetMethod("ResetCache",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,null);UnityEngine.Object.Flush();}
 public static void Main(){
 var parent=new GameObject("trs-check");parent.transform.localPosition=new Vector3(2,3,4);parent.transform.localRotation=Quaternion.Euler(0,90,0);parent.transform.localScale=new Vector3(2,2,2);var child=new GameObject("trs-child");child.transform.SetParent(parent.transform,false);child.transform.localPosition=new Vector3(0,0,1);Check((child.transform.position-new Vector3(4,3,4)).magnitude<.0001f,"hierarchical TRS sanity");var before=child.transform.position;child.transform.SetParent(null,true);Check((child.transform.position-before).magnitude<.0001f,"world-preserving reparent sanity");UnityEngine.Object.Destroy(child);UnityEngine.Object.Destroy(parent);UnityEngine.Object.Flush();
 foreach(HeroClass hero in Enum.GetValues(typeof(HeroClass)))foreach(int upgrade in new[]{0,3,7,10})foreach(bool fashionFirst in new[]{false,true}){
 var host=new GameObject("hero");var model=CombatModel.Hero(host.transform,hero);Check(model.GetComponentsInChildren<TailoredCloth>(true).Single().Profile==hero,"actual Hero factory passes class to rear silhouette before EnhanceHero");UnityEngine.Object.Flush();var gear=Enum.GetValues(typeof(ItemSlot)).Cast<ItemSlot>().Select(slot=>new ItemData{id=slot.ToString(),slot=slot,rarity=Rarity.Legendary,level=100,upgradeLevel=upgrade}).ToArray();var wings=new FashionData{id="max wings",slot=FashionSlot.Wings,rarity=Rarity.Legendary};var weapon=new FashionData{id="max weapon",slot=FashionSlot.Weapon,rarity=Rarity.Legendary};
 if(fashionFirst)model.ApplyFashion(wings,weapon);model.ApplyEquipment(gear[0],gear[1],gear[2]);model.ApplyFashion(wings,weapon);UnityEngine.Object.Flush();
 Check(new EquipmentAppearance(gear[0]).Tier==4,"fixture really selects T4");var relic=Find(model,"Equipped Relic");var rv=Vertices(relic,model.transform);Check(rv.Length>0,"actual relic has mesh vertices");Check(rv.All(v=>Math.Abs(v.x)<.245f&&v.y>.65f&&v.y<1.045f&&v.z>=.39f-.0001f&&v.z<.535f),"actual relic vertices preserve face/chest/grip/back envelope");
 Check(relic.parent.name=="Spine"&&Math.Abs(relic.localPosition.y+1.12f)<.0001f,"relic attached to compensated spine origin");var equip=Find(model,"Equipped Weapon");var fw=Find(model,"Fashion Weapon");Check(equip.parent==fw.parent,"fashion and equipped weapon share the class wrist anchor");string costume=hero==HeroClass.Vanguard?"Raised breastplate":hero==HeroClass.Arcanist?"Equipped robe skirt":hero==HeroClass.Ranger?"Asymmetric leather chest wrap":"Spirit ritual bib";Check(Find(model,costume).gameObject.activeInHierarchy,"equipped armor preserves actual class identity geometry");Check(Find(model,"Fashion Wings").parent.name=="Spine","back fashion follows spine");
 var all=model.GetComponentsInChildren<MeshFilter>(false);Check(all.Length>50&&all.Length<250,"bounded combined production part count");foreach(var f in all){Check(f.sharedMesh!=null&&!f.sharedMesh.destroyed&&f.GetComponent<Renderer>().sharedMaterial!=null&&!f.GetComponent<Renderer>().sharedMaterial.destroyed,"live mesh/material for visible piece");Check(f.sharedMesh.vertices.All(v=>float.IsFinite(v.x)&&float.IsFinite(v.y)&&float.IsFinite(v.z)),"finite actual recipe vertices");}
 if(hero==HeroClass.Arcanist||hero==HeroClass.Summoner){var shaft=Find(model,"Inlaid staff");var sv=Vertices(shaft,equip.parent);Check(Math.Abs(sv.Min(v=>v.y)+.94f)<.0001f,"T4 staff lower end stays at authored safe bound");Check(Vertices(shaft,model.transform).Min(v=>v.y)>.09f,"staff bottom clears ground in constructed rest rig");Check(equip.parent.name=="Staff Wrist","caster weapon identity retained");}
 else if(hero==HeroClass.Vanguard){Check(Find(model,"Tiered blade").parent==equip,"actual sword blade belongs to sword equipment");Vector3 tip;Check(model.TryGetWeaponVisualAnchor(WeaponVisualAnchor.SwordTip,out tip)&&Vertices(Find(model,"Tiered blade"),equip.parent).Max(v=>v.y)>1.7f,"T4 blade agrees with real tip anchor family");}
 else {Check(equip.parent.name=="Bow","ranger retains bow class rig");Check(Find(model,"Drawn Bowstring").GetComponent<LineRenderer>().points[0].y>.8f,"T4 bowstring uses upgraded real tips");}
 int objects=Live<GameObject>(),meshes=Live<Mesh>(),materials=Live<Material>();for(int i=0;i<5;i++){model.ApplyEquipment(gear[0],gear[1],gear[2]);model.ApplyFashion(wings,weapon);}UnityEngine.Object.Flush();Check(Live<GameObject>()==objects&&Live<Mesh>()==meshes&&Live<Material>()==materials,"identical composition is allocation-free");
 for(int cycle=0;cycle<4;cycle++){var old=Find(model,"Equipped Relic");model.ApplyEquipment(null,null,null);Check(!old.gameObject.activeSelf,"unequip hides old geometry before deferred destruction");model.ApplyFashion(null,null);UnityEngine.Object.Flush();model.ApplyEquipment(gear[0],gear[1],gear[2]);model.ApplyFashion(wings,weapon);UnityEngine.Object.Flush();Check(Live<GameObject>()==objects&&Live<Mesh>()==meshes&&Live<Material>()==materials,"swap cycles keep resources bounded");}
 UnityEngine.Object.Destroy(host);UnityEngine.Object.Flush();Check(Live<GameObject>()==0&&Live<Material>()==0,"model disposal releases hierarchy and own palette");Check(UnityEngine.Object.All.OfType<Mesh>().Where(m=>!m.destroyed).All(m=>m.name.StartsWith("Shared costume")||m.name.StartsWith("Emberfall shared")),"only shared shape caches survive model disposal");ResetMeshes();Check(Live<Mesh>()==0,"shared cache reset releases all remaining meshes");
 }
 Console.WriteLine("PASS: "+checks+" production composition assertions; 4 heroes x 4 upgrade ranks x 2 equip orders, T4 + highest fashion. Static TRS/resources only, no Unity animation or GPU validation.");
 }
}
